; WS2812B LED chain; tape word 0 = LED count n, words 1..n = GRB colours; latched, repeated for ever
; Generated by escgen from protocols/ws2812_gen.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: Worldsemi WS2812B datasheet: T0H 0.4 us, T1H 0.8 us, bit 1.25 us +/- 600 ns, reset low >= 50 us (newer parts 280 us; 300 us here)
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 3
.default CLK_KHZ, 25000                ; core clock in kHz
.equ T0H, CLK_KHZ * 2 // 5000
.equ T1H, CLK_KHZ * 4 // 5000
.equ TBIT, CLK_KHZ * 31 // 25000
.equ TLATCH, CLK_KHZ * 300 // 1000
.default PIN_D, 0
.equ P_D, 1 << PIN_D

.own  PIN_D, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_D, 0, P_D                 ; idle levels
    ADDT  1
packet:
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    MOVI  r2, 0                       ; tape address
    LDT   r3, r2, 0                   ; words in this packet
    ADDI  r2, 1
    CMPI  r3, 0
    JZ    packet                      ; an empty packet: look again
next_word:
    LDT   r0, r2, 0
    SHL   r0, 8                       ; the field's first bit to bit 31
    LDSH  r0                          ; 24 bits, MSB first
    LDLC  24
bit1:
    EMIT  P_D, P_D, P_D
    ADDT  T0H
    EMITX P_D, MSB, P_D               ; data bit
    ADDT  T1H - T0H
    EMIT  P_D, 0, P_D
    ADDT  TBIT - T1H
    DJNZ  bit1
    ADDI  r2, 1
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last word
    JNZ   next_word
    ADDT  TLATCH                      ; latch: no change, no event
    JMP   packet
